//@ProcessingGroup("creditor")
@Component("creditor-projector")
public class CreditorProjector extends CreditorEntityProjector {
		
	// core constructor
	public CreditorProjector(ProjectorRegistry registry,
									CreditorRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateCreditorEvent
     */
    @EventHandler( payloadType=CreateCreditorEvent.class )
    public void handle( CreateCreditorEvent event) {
	    LOGGER.info("handling CreateCreditorEvent - " + event );
	    Creditor entity = new Creditor();
            entity.setCreditorId( event.getCreditorId() );
            entity.setName( event.getName() );
            entity.setBic( event.getBic() );
            entity.setAddress( event.getAddress() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreditor( entity );
    }

    /*
     * @param	event UpdateCreditorEvent
     */
    @EventHandler( payloadType=UpdateCreditorEvent.class )
    public void handle( UpdateCreditorEvent event) {
    	LOGGER.info("handling UpdateCreditorEvent - " + event );
    	
	    Creditor entity = new Creditor();
            entity.setCreditorId( event.getCreditorId() );
            entity.setName( event.getName() );
            entity.setBic( event.getBic() );
            entity.setAddress( event.getAddress() );
            entity.setMandates( event.getMandates() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCreditor( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreditor( entity );        
    }
    
    /*
     * @param	event DeleteCreditorEvent
     */
    @EventHandler( payloadType=DeleteCreditorEvent.class )
    public void handle( DeleteCreditorEvent event) {
    	LOGGER.info("handling DeleteCreditorEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Creditor entity = delete( event.getCreditorId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreditor( entity );

    }    


    /*
     * @param	event AssignMandatesToCreditorEvent
     */
    @EventHandler( payloadType=AssignMandatesToCreditorEvent.class)
    public void handle( AssignMandatesToCreditorEvent event) {
	    LOGGER.info("handling AssignMandatesToCreditorEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    Creditor entity = addToMandates(event.getCreditorId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCreditor( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreditor( entity );
    }
    

/*
 * @param	event RemoveMandatesFromCreditorEvent
 */
@EventHandler( payloadType=RemoveMandatesFromCreditorEvent.class)
public void handle( RemoveMandatesFromCreditorEvent event) {
    LOGGER.info("handling RemoveMandatesFromCreditorEvent - " + event );

    Creditor entity = removeFromMandates(event.getCreditorId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindCreditor( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllCreditor( entity );
}



    /**
     * Method to retrieve the Creditor via an CreditorPrimaryKey.
     * @param 	id Long
     * @return 	Creditor
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Creditor handle( FindCreditorQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCreditorId() );
    }
    
    /**
     * Method to retrieve a collection of all Creditors
     *
     * @param	query	FindAllCreditorQuery 
     * @return 	List<Creditor> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Creditor> handle( FindAllCreditorQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCreditor,
 * but only if the id matches
 *
 * @param		entity	Creditor
 */
	protected void emitFindCreditor( Creditor entity ) {
		LOGGER.info("handling emitFindCreditor" );
		
	    queryUpdateEmitter.emit(FindCreditorQuery.class,
	                            query -> query.getFilter().getCreditorId().equals(entity.getCreditorId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCreditor
	 * 
	 * @param		entity	Creditor
	 */
	protected void emitFindAllCreditor( Creditor entity ) {
		LOGGER.info("handling emitFindAllCreditor" );
		
	    queryUpdateEmitter.emit(FindAllCreditorQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(CreditorProjector.class.getName());

}
